<?php require_once __DIR__.'/../classes/Database.php';require_once __DIR__.'/../classes/Session.php';Session::start();$pdo=(new Database())->getConnection();$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT o.*,e.nom entreprise,s.libelle secteur,v.libelle ville,tc.libelle type_contrat FROM offre o JOIN entreprise e ON o.id_entreprise=e.id JOIN secteur s ON o.id_secteur=s.id JOIN ville v ON o.id_ville=v.id JOIN type_contrat tc ON o.id_type_contrat=tc.id WHERE o.id=:id AND o.statut='publiee'");$q->execute(['id'=>$id]);$o=$q->fetch();if(!$o)exit('Offre introuvable.');$msg=$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if (!Session::verifyCsrf($_POST['csrf_token'] ?? null)) {
    http_response_code(403);
    exit('Requête invalide.');
} if(!Session::get('candidat_connecte')){header('Location: login.php');exit;}$lettre=trim($_POST['lettre_motivation']??'');$cid=(int)Session::get('candidat_id');if(!$lettre)$err='Lettre obligatoire.';else{$q=$pdo->prepare('SELECT id FROM candidature WHERE id_candidat=:c AND id_offre=:o');$q->execute(['c'=>$cid,'o'=>$id]);if($q->fetch())$err='Vous avez déjà candidaté.';else{$q=$pdo->prepare("INSERT INTO candidature(id_candidat,id_offre,lettre_motivation,statut) VALUES(:c,:o,:l,'en_attente')");$q->execute(['c'=>$cid,'o'=>$id,'l'=>$lettre]);$msg='Candidature envoyée.';}}}?><!doctype html><html lang="fr"><head><meta charset="UTF-8"><title><?=htmlspecialchars($o['titre'])?></title></head><body><h1><?=htmlspecialchars($o['titre'])?></h1><p><?=htmlspecialchars($o['entreprise'])?> — <?=htmlspecialchars($o['ville'])?> — <?=htmlspecialchars($o['secteur'])?> — <?=htmlspecialchars($o['type_contrat'])?></p><p><?=nl2br(htmlspecialchars($o['description']))?></p><?php if($msg):?><p><?=htmlspecialchars($msg)?></p><?php endif;?><?php if($err):?><p><?=htmlspecialchars($err)?></p><?php endif;?><?php if(Session::get('candidat_connecte')):?><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(Session::csrfToken()) ?>"><textarea name="lettre_motivation" rows="8" required></textarea><button>Postuler</button></form><?php else:?><a href="login.php">Connectez-vous pour postuler.</a><?php endif;?><p><a href="offres.php">Retour aux offres</a></p></body></html>